/** Source-reviewed additions for Dumfries, Stranraer, Elgin, Oban and Fort William. */
import { pathway } from "./internationalSupportDirectoryPathway.js";

const UK = "United Kingdom";
const checkedAt = "2026-11-23";
const records = [];

function add(city, category, slug, name, type, description, phone, url, source, extra = {}) {
  records.push(pathway(UK, "GB", category, `scotland-rural-${city.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${slug}`, name, type, description, phone, url, source, {
    city, state: "Scotland", region: `${city}, Scotland`, checkedAt, ...extra,
  }));
}

// Dumfries: food access, housing, recovery, peer and family pathways.
add("Dumfries", "food.essentials", "apex-foodbank", "APEX Dumfries Foodbank", "Foodbank and emergency food parcels", "The council lists this foodbank run with local churches and facilitated by Apex Scotland. Contact first to ask how to access a parcel, whether a referral or voucher is needed, and the current collection arrangements.", "01387 256310", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/find-food-bank/apex-dumfries-foodbank", "Dumfries and Galloway Council", { address: "77–79 Friars Vennel, Dumfries DG1 2RF", alternatePhone: "07841 052007", locationLine: "Call to confirm referral requirements and current collection details" });
add("Dumfries", "food.essentials", "first-base-foodbank", "First Base Foodbank", "Food parcels and practical support", "Dumfries and Galloway Council lists First Base as a local food parcel provider. Contact the service before travelling to check eligibility, opening arrangements, and whether you need a referral.", "01387 279680", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/find-food-bank/first-base-foodbank", "Dumfries and Galloway Council", { address: "6 Buccleuch Street, Dumfries DG1 2AH", locationLine: "Food parcels · contact provider to confirm access and current hours" });
add("Dumfries", "food.essentials", "queen-of-south-foodbank", "Queen of the South FC Foodbank", "Walk-in community foodbank", "The council describes a drop-in foodbank where anyone may visit and access the food available that day. The published listing gives an evening service; call to confirm today's opening and availability before making the journey.", "01387 254853", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/find-food-bank/queen-south-football-club-foodbank", "Dumfries and Galloway Council", { address: "Palmerston Park, 76–94 Terregles Street, Dumfries DG2 9BA", locationLine: "Council-listed evening drop-in · food supply varies; call first" });
add("Dumfries", "food.essentials", "river-of-life-foodbank", "River of Life Foodbank", "Evening food support and community contact", "The council lists this evening food support at Dumfries railway station. Contact ahead to confirm the current time, access arrangements and the type of food support available.", "07475 771347", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/find-food-bank/river-life-foodbank", "Dumfries and Galloway Council", { address: "River of Life Centre, Dumfries Station, Lovers Walk, Dumfries DG1 1NF", locationLine: "Council-listed evening service · confirm hours and access before travelling" });
add("Dumfries", "housing", "homelessness-assessment", "Dumfries and Galloway Council — homelessness and housing support", "Homelessness assessment and accommodation support", "The council can assess homelessness, arrange emergency accommodation where appropriate and connect people with support workers, benefits and debt advice. If you have nowhere to stay tonight, use the council's published urgent-housing contact. Its after-hours contact covers evenings and weekends.", "01387 260783", "https://www.dumfriesandgalloway.gov.uk/housing/homelessness", "Dumfries and Galloway Council", { address: "122–124 Irish Street, Dumfries DG1 2PB", alternatePhone: "Urgent help after 5pm or weekends: 0303 333 3001", locationLine: "Weekday office: 9am–5pm · if no place to stay tonight, call the listed urgent number" });
add("Dumfries", "grants", "scottish-welfare-fund", "Dumfries and Galloway Council — Scottish Welfare Fund", "Crisis Grants and Community Care Grants", "Apply to the Scottish Welfare Fund for a Crisis Grant after an emergency or a Community Care Grant to help establish or maintain a home. Awards are assessed against current rules and available evidence; a grant is not guaranteed. Contact the council to check the application route and urgent processing options.", "03033 333007", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/apply-benefits-financial-support/crisis-grant", "Dumfries and Galloway Council", { locationLine: "Means-tested council fund · application and award depend on current criteria" });
add("Dumfries", "programs", "we-are-with-you-drug-alcohol", "We Are With You — Dumfries", "Confidential drug and alcohol support, harm reduction and advice", "This free service supports adults aged 16+ living in Dumfries and Galloway who are concerned about their own or someone else's alcohol or drug use. Support includes advice, harm reduction and routes into further care. Self-referral is available; confirm how the current appointment or collection process works before attending.", "01387 263208", "https://dghscp.co.uk/alcohol-drugs-partnership-adp/", "Dumfries and Galloway Health and Social Care Partnership / We Are With You", { address: "79 Buccleuch Street, Dumfries DG1 2AB", email: "allatdumfriesandgalloway@wearewithyou.org.uk", locationLine: "Age 16+ · free and confidential · weekdays and weekends listed by regional service" });
add("Dumfries", "programs", "alcohol-drug-support-talking-therapies", "Alcohol and Drug Support South West Scotland — Dumfries", "Talking therapy and community support for alcohol, drug or gambling concerns", "ADS offers community-based help to people affected by their own or another person's alcohol, drug or gambling problems. Its qualified therapists use a range of approaches. Contact the Dumfries team to discuss support and current referral or appointment arrangements.", "01387 259999", "https://dghscp.co.uk/alcohol-drugs-partnership-adp/", "Dumfries and Galloway Health and Social Care Partnership / ADS", { address: "79 Buccleuch Street, Dumfries DG1 2AB", locationLine: "Individual and family support · contact for current access" });
add("Dumfries", "programs", "nhs-specialist-drug-alcohol", "NHS Specialist Drug and Alcohol Service — Dumfries", "Assessment and treatment for complex alcohol or drug dependence", "The NHS service provides assessment and an agreed care plan for adults with dependency or complex substance-use needs. Options can include medication, detoxification, psychological interventions, occupational therapy and referral for residential rehabilitation. Self-referral is accepted; call the service to discuss the right site and current intake.", "01387 244555", "https://dghscp.co.uk/specialist-drug-and-alcohol-service/", "Dumfries and Galloway Health and Social Care Partnership / NHS", { address: "Lochfield Road Primary Care Centre, 12–28 Lochfield Road, Dumfries DG2 9BH", alternatePhone: "01387 244550", locationLine: "Adults 18+ · self-referral accepted · Monday–Friday, 8:30am–5pm listed" });
add("Dumfries", "peer", "recovery-together-community", "Dumfries and Galloway Recovery Together — Dumfries group", "Peer-led recovery community", "A local recovery community listed by the regional Alcohol and Drug Partnership. People with shared recovery goals support one another, and volunteering or training opportunities may be available. Contact the group to confirm the current Dumfries meeting arrangements and whether new members can attend.", null, "https://dghscp.co.uk/alcohol-drugs-partnership-adp/", "Dumfries and Galloway Health and Social Care Partnership / Recovery Together", { email: "dumfriesandgallowayrecoverytog@gmail.com", locationLine: "Peer support · local group listed for Dumfries; confirm current venue and schedule" });
add("Dumfries", "peer", "female-recovery-warriors", "Female Recovery Warriors — Dumfries", "Women-only peer support for recovery", "The local Alcohol and Drug Partnership describes a women-only peer group for adults 18+ working on recovery, confidence and social connection. It is currently described as a closed group while the model is being tested, so contact the listed host to ask whether it is accepting participants or has an alternative route.", "01387 263208", "https://dgadp.co.uk/services-support/female-recovery-warriors/", "Dumfries and Galloway Alcohol and Drug Partnership", { address: "We Are With You, 79 Buccleuch Street, Dumfries DG1 2AB", locationLine: "Women 18+ · source currently describes a closed group; call to check access" });
add("Dumfries", "programs", "mental-health-association", "Dumfries and Galloway Mental Health Association", "Community mental-health, daily-living and family support", "The association supports people with mental-health conditions and their families, including help with community participation and day-to-day living. Contact the service to discuss the available support, eligibility and current referral process.", "01387 268615", "https://dgmha.org/", "Dumfries and Galloway Mental Health Association", { address: "Dudgeon House, The Crichton Estate, Bankend Road, Dumfries DG1 4ZN", email: "enquiries@dgmha.org", locationLine: "Dumfries and Galloway residents · phone or email to discuss support" });

// Stranraer: Wigtownshire-specific food, housing, treatment and mental-health access.
add("Stranraer", "food.essentials", "apex-foodbank", "APEX Stranraer Foodbank", "Food parcels with referral or voucher requirements", "The council lists this Wigtownshire foodbank at Apex Scotland. Contact before visiting to confirm the referral or voucher route, opening time and current collection arrangements.", "01776 700973", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/find-food-bank/apex-stranraer-foodbank", "Dumfries and Galloway Council", { address: "2 Back Rampart, High Street, Stranraer DG9 7LW", locationLine: "Council listing says voucher required · confirm current access before travelling" });
add("Stranraer", "food.essentials", "rhins-basics-foodbank", "Rhins Basics Foodbank", "Local food parcel delivery on request", "The council lists Rhins Basics as a Wigtownshire food support provider that can deliver parcels on request. Contact to explain what is needed and confirm current eligibility, delivery area and timing.", "07715 677204", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/find-food-bank/rhins-basics-foodbank", "Dumfries and Galloway Council", { address: "Fairhurst Road, Stranraer DG9 7AP", locationLine: "Delivery may be available on request · confirm area and timing" });
add("Stranraer", "food.essentials", "fed-up-community-cafe", "Fed Up Community Café", "Free food, drinks and community support", "The council lists this Stranraer café as offering free food, drinks and support. Check the current weekday opening hours before travelling and ask the team what support is available that day.", "01776 706159", "https://www.dumfriesandgalloway.gov.uk/benefits-financial-support/find-food-bank/fed-community-cafe", "Dumfries and Galloway Council", { address: "12 Bridge Street, Stranraer DG9 7HY", locationLine: "Council-listed weekday café · call to confirm hours and current service" });
add("Stranraer", "housing", "homelessness-assessment", "Dumfries and Galloway Council — Stranraer homelessness support", "Homelessness assessment, emergency accommodation and tenancy help", "The council's Stranraer office can assess housing and homelessness needs and connect people with emergency accommodation and support. If you have nowhere to stay tonight, say so when calling; the council publishes a local urgent contact and a shared after-hours route. Accommodation depends on assessment.", "01776 888312", "https://www.dumfriesandgalloway.gov.uk/housing/homelessness", "Dumfries and Galloway Council", { address: "Ashwood House, Sun Street, Stranraer DG9 7JJ", alternatePhone: "After 5pm or weekends: 0303 333 3001", locationLine: "Weekday office-hours contact · local urgent and shared after-hours numbers are listed separately" });
add("Stranraer", "programs", "we-are-with-you-drug-alcohol", "We Are With You — Stranraer", "Confidential drug and alcohol support, harm reduction and advice", "This free service supports adults aged 16+ living in Dumfries and Galloway who are concerned about their own or someone else's alcohol or drug use. Support includes advice, harm reduction and routes into further care. Contact the Stranraer office to confirm the best current access method before attending.", "01776 705904", "https://dghscp.co.uk/alcohol-drugs-partnership-adp/", "Dumfries and Galloway Health and Social Care Partnership / We Are With You", { address: "32 Charlotte Street, Stranraer DG9 7EF", email: "allatdumfriesandgalloway@wearewithyou.org.uk", locationLine: "Age 16+ · free and confidential · contact to confirm current appointments" });
add("Stranraer", "programs", "alcohol-drug-support-talking-therapies", "Alcohol and Drug Support South West Scotland — Stranraer", "Talking therapy and community support for alcohol, drug or gambling concerns", "ADS offers community-based help to people affected by their own or another person's alcohol, drug or gambling problems. Its qualified therapists use a range of approaches. Contact the Stranraer team to discuss support and current referral or appointment arrangements.", "01776 70262", "https://dghscp.co.uk/alcohol-drugs-partnership-adp/", "Dumfries and Galloway Health and Social Care Partnership / ADS", { address: "32 Charlotte Street, Stranraer DG9 7EF", locationLine: "Individual and family support · contact for current access" });
add("Stranraer", "programs", "nhs-specialist-drug-alcohol", "NHS Specialist Drug and Alcohol Service — Wigtownshire", "Assessment and treatment for complex alcohol or drug dependence", "The NHS service provides assessment and an agreed care plan for adults with dependency or complex substance-use needs. Treatment options can include medication, detoxification, psychological interventions, occupational therapy and referral for residential rehabilitation. Self-referral is accepted; call to confirm the Stranraer appointment route.", "01387 244555", "https://dghscp.co.uk/specialist-drug-and-alcohol-service/", "Dumfries and Galloway Health and Social Care Partnership / NHS", { address: "Innistaigh, Dalrymple Street, Stranraer DG9 7DQ", locationLine: "Adults 18+ · self-referral accepted · regional service, call to confirm local appointment" });
add("Stranraer", "programs", "wigtownshire-community-mental-health", "Wigtownshire Community Mental Health Team", "Adult and older-adult community mental-health nursing", "The NHS describes a Wigtownshire team based in Stranraer, with weekday and weekend operating hours. Contact the relevant adult or older-adult team to discuss access. On public holidays, the source directs people to the Dumfries crisis team; call ahead if you need urgent assessment.", "01776 707806", "https://dghscp.co.uk/community-mental-health-nursing-team/", "Dumfries and Galloway Health and Social Care Partnership / NHS", { address: "Innistaigh, Dalrymple Street, Stranraer DG9 7EH", alternatePhone: "Older Adult Team: 01776 707807", locationLine: "Adult and older-adult teams · source lists weekday and weekend hours; public holiday route differs" });
add("Stranraer", "programs", "camhs-oak-tree", "CAMHS — The Oak Tree Family Centre, Stranraer", "Children and young people's mental-health advice and assessment", "Dumfries and Galloway CAMHS provides a contact route for children, young people and families, with a local base at The Oak Tree in Stranraer. A mental-health professional can be reached by phone during the published weekday afternoon window; contact the team for guidance and the correct referral route.", "01387 244662", "https://dghscp.co.uk/camhs/contact/", "Dumfries and Galloway Health and Social Care Partnership / NHS", { address: "The Oak Tree Family Centre, Dalrymple Street, Stranraer DG9 7EH", email: "dg.CAMHS-mail@nhs.scot", locationLine: "Children, young people and families · call for current referral and appointment details" });
add("Stranraer", "peer", "recovery-together-community", "Dumfries and Galloway Recovery Together — Stranraer group", "Peer-led recovery community", "The regional Alcohol and Drug Partnership lists a Recovery Together group in Stranraer. Peers share recovery goals and may have opportunities to volunteer or train. Contact the group to confirm whether the local group is currently meeting and how to join.", null, "https://dghscp.co.uk/alcohol-drugs-partnership-adp/", "Dumfries and Galloway Health and Social Care Partnership / Recovery Together", { email: "dumfriesandgallowayrecoverytog@gmail.com", locationLine: "Peer support · Stranraer group listed; confirm current venue and session times" });
add("Stranraer", "grants", "stranraer-citizens-advice-benefits", "Stranraer Citizens Advice Bureau — benefits and financial guidance", "Free advice on benefits, debt, money, grants and cost-of-living support", "The local bureau provides benefits advice and practical guidance on money, debt, grants and cost-of-living support. Advisers can help identify options and application routes, but do not guarantee eligibility or award decisions. Contact to confirm appointment or drop-in availability and ask what documents to bring.", "0300 303 4321", "https://www.dagcas.org/dagcas-location/stranraer-cab/", "Dumfries and Galloway Citizens Advice Service", { address: "Burns House, 32 Harbour Street, Stranraer DG9 7RD", locationLine: "Published weekday opening hours · call to confirm current access and appointment availability" });

// Elgin: distinct Moray access routes and named local providers.
add("Elgin", "programs", "arrows-drug-alcohol", "Quarriers Arrows — Moray drug and alcohol support", "Confidential substance-use advice, assessment and recovery support", "Arrows supports people in Moray concerned about their own or someone else's alcohol or drug use, including confidential advice, groups and onward care pathways. Contact directly to discuss access and current group times; do not assume walk-in capacity.", "01343 610500", "https://www.quarriers.org.uk/blog/service/drug-and-alcohol-recovery/arrows-service-2/", "Quarriers", { alternatePhone: "07812 228547", address: "40 Moss Street, Elgin IV30 1LT", locationLine: "Moray residents · call to discuss access and current group schedule" });
add("Elgin", "housing", "moray-housing-support", "Moray Council — Housing Support Team", "Housing-related support to sustain a tenancy and connect to specialist help", "The council's Housing Support Team can help with accommodation, health, emotional support, finances, practical skills and links to specialist services. Contact the team to discuss an assessment and whether the support fits your circumstances; availability and eligibility are assessed individually.", "0300 1234 566", "https://www.moray.gov.uk/housing-and-homelessness/housing-options-homelessness-and-support/housing-options-guide/housing-options-guide-7/", "Moray Council", { address: "PO Box 6760, Elgin IV30 1BX", email: "housingsupportteam@moray.gov.uk", locationLine: "Weekdays 8:45am–5pm listed · contact for assessment and eligibility" });
add("Elgin", "housing", "moray-homelessness-housing-options", "Moray Council — homelessness and housing options", "Housing options and urgent homelessness contact", "Moray Council lists a daytime Housing and Property contact and a separate out-of-hours social work emergency route for people facing immediate homelessness. Explain the urgency and ask the team which assessment or accommodation route applies; temporary accommodation is subject to assessment.", "0300 123 4566", "https://www.moray.gov.uk/contact-us/", "Moray Council", { alternatePhone: "Out of hours: 03457 565656", locationLine: "Daytime housing contact and separate out-of-hours urgent route; eligibility is assessed" });
add("Elgin", "grants", "moray-money-advice-income-maximisation", "Moray Council — Money Advice and Income Maximisation", "Benefits, debt and income-maximisation advice", "Moray Council's Money Advice and Income Maximisation teams help residents explore benefits, money and debt support. Call the appropriate team to discuss a benefits check or advice route; eligibility for benefits is decided by the relevant administering authority.", "0300 123 4563", "https://www.moray.gov.uk/contact-us/", "Moray Council", { alternatePhone: "Income Maximisation: 0300 123 4563", locationLine: "Weekdays 8:45am–5pm council contact centre · ask for Money Advice or Income Maximisation" });
add("Elgin", "grants", "moray-scottish-welfare-fund", "Moray Council — Scottish Welfare Fund", "Crisis Grants and Community Care Grants", "Apply for a council-assessed Crisis Grant following an emergency or a Community Care Grant to help establish or maintain a home. The council assesses applications against the current rules and available evidence; approval and amount are not guaranteed. Online and phone applications are available. For an out-of-hours emergency, use the council's published emergency contact.", "01343 563456", "https://www.moray.gov.uk/benefits-and-grants/benefits-service/scottish-welfare-fund/apply-to-the-scottish-welfare-fund/", "Moray Council", { email: "awards@moray.gov.uk", alternatePhone: "Out-of-hours emergency: 03457 565656", locationLine: "Phone applications weekdays 8:45am–5pm · means-tested; grant not guaranteed" });
add("Elgin", "programs", "community-mental-health-access", "Moray Health and Social Care Partnership — Access Care Team", "Community-care assessment and mental-health social-work access", "The Access Care Team is the first contact for adult community-care enquiries and can provide information, initial screening and referrals to appropriate services. Moray's mental-health social-work team provides assessment and recovery-focused support. Contact the Access Team to discuss the right route and current service criteria.", "01343 563999", "https://www.moray.gov.uk/social-care-and-health/community-care/contact-community-care/", "Moray Health and Social Care Partnership / Moray Council", { address: "2–10 High Street, Elgin IV30 1BY", email: "accesscareteam@moray.gov.uk", locationLine: "Weekdays 8:45am–5pm listed · emergency out-of-hours social-work line differs" });
add("Elgin", "peer", "quarriers-carer-support-moray", "Quarriers Carer Support Service — Moray", "Information, support plans and groups for unpaid carers", "Quarriers supports adult and young unpaid carers across Moray with information, advice, listening support and carer planning. People can contact the service themselves or ask a trusted person to make contact. Ask about current groups and the referral process; support is tailored to individual caring needs.", "01343 556031", "https://carers.quarriers.org.uk/services/moray/", "Quarriers Carer Support Service", { address: "232 High Street, Elgin IV30 1BA", email: "carersmoray@quarriers.org.uk", locationLine: "Adult and young carers across Moray · contact directly to discuss support" });
add("Elgin", "peer", "elgin-youth-cafe", "Elgin Youth Cafe", "Youth drop-in, safe social space and employability activities", "Moray Council lists a free youth café with separate drop-in sessions for ages 11–18 and 16–24, alongside activities, volunteering and work or training opportunities. Contact the café before attending to confirm the current timetable and age-specific session.", "01343 548300", "https://www.moray.gov.uk/jobs-and-employment/employability/skills-pipeline-overview-of-services/elgin-youth-cafe/", "Moray Council / Elgin Youth Cafe", { email: "kate@elginyouthcafe.org", locationLine: "Free youth service · age-specific sessions; confirm current timetable before attending" });
add("Elgin", "food.essentials", "moray-food-plus-crisis-food", "Moray Food Plus — Elgin food and hardship support", "Crisis food support, pantry and wider poverty assistance", "Moray Food Plus describes crisis food support and broader poverty-prevention services, including food pantries, rural outreach and money advice. Contact the Elgin office to explain what is needed and confirm how to access the relevant service; do not assume walk-in food parcels or same-day availability.", "01343 208293", "https://morayfoodplus.org.uk/contact-us/", "Moray Food Plus", { address: "203 High Street, Elgin IV30 1DJ", email: "admin@morayfoodplus.org.uk", locationLine: "Office contact Monday–Friday, 9am–12:30pm · confirm crisis-food access before attending" });

// Oban: local food, housing support, mental health, carers and youth.
add("Oban", "food.essentials", "hope-kitchen-food-parcels", "Hope Kitchen — Oban food parcels and community café", "Food parcels and donation-based community food support", "Argyll and Bute Council lists Hope Kitchen as providing food parcels from donations. Contact to ask about the current parcel route and what support is available; availability depends on donations. Its community café also offers a place to connect.", "01631 565730", "https://www.argyll-bute.gov.uk/my-community/community-food-organisations-argyll-and-bute", "Argyll and Bute Council / Hope Kitchen", { address: "2 Argyll Street, Oban PA34 5SG", email: "info@hopekitchen.org.uk", locationLine: "Donation-dependent parcels · contact before travelling to confirm current arrangements" });
add("Oban", "housing", "council-housing-office", "Argyll and Bute Council — Oban housing and homelessness office", "Housing options, homelessness assessment and local housing contact", "The council lists the Oban housing office for local housing matters and a separate out-of-hours homelessness line. Call to explain your circumstances and request an assessment; emergency accommodation and other support depend on council assessment.", "01631 567926", "https://www.argyll-bute.gov.uk/housing/housing-support", "Argyll and Bute Council", { address: "Municipal Buildings, Albany Street, Oban PA34 4AW", alternatePhone: "Out of hours homelessness: 0345 056 5457", locationLine: "Local housing office; use the listed out-of-hours line for urgent homelessness" });
add("Oban", "housing", "carr-gomm-housing-support", "Carr Gomm — Oban housing support", "Housing-related support and tenancy sustainment", "Argyll and Bute Council names Carr Gomm as a housing-support provider in Oban. The service can help with tenancy responsibilities and connecting to community support. Contact to discuss eligibility, appointment arrangements and current capacity; appointments may need to be arranged in advance.", "01631 563375", "https://www.argyll-bute.gov.uk/housing/housing-support", "Argyll and Bute Council / Carr Gomm", { address: "Don Mor Cottage, Albany Street, Oban PA34 4LQ", locationLine: "Council-listed support provider · contact to discuss referral and appointment" });
add("Oban", "programs", "community-mental-health-team", "Argyll and Bute Community Mental Health Team — Oban", "Local mental-health assessment and care management", "The council describes mental-health assessment and care management for people with mental-health difficulties, including severe or enduring illness, through local teams. The Oban, Lorn and Isles team is based at Willowview. Contact the team for access and referral guidance; it is not an emergency dispatch service.", "01546 605517", "https://www.argyll-bute.gov.uk/social-care-and-health/health-and-medical-information/mental-health", "Argyll and Bute Council / Health and Social Care Partnership", { address: "Willowview Community Care Centre, Lower Soroba, Oban PA34 4SB", locationLine: "Oban, Lorn and the Isles team · call for access and referral advice" });
add("Oban", "peer", "north-argyll-carers-centre", "North Argyll Carers Centre", "Support plans, groups and advice for unpaid carers", "The centre supports unpaid carers in Oban, Lorn and the Isles with information, carer support plans, events and groups, including support for young carers and rural or island carers. Carers can self-contact by phone, email or drop-in; ask for current sessions and any appointment needs.", "01631 564422", "https://www.northargyllcarers.org.uk/", "North Argyll Carers Centre", { address: "Albany Street, Oban PA34 4AL", email: "info@northargyllcarers.org.uk", locationLine: "Unpaid carers · weekdays listed; drop-in and arranged appointments available" });
add("Oban", "peer", "oban-youth-cafe", "Oban Youth Cafe", "Youth social space and youth-work support", "The Oban Youth Cafe Project offers young people a place to meet and build relationships with youth-work staff. The local service listing gives an Albany Terrace address and contact number; contact the project for the age range, current schedule and activities before attending.", "01631 567399", "https://abcd.scot/services/oban-youth-cafe/", "Argyll and Bute Council community service directory / Oban Youth Cafe Project", { address: "4 Albany Terrace, Oban PA34 5NY", email: "kirsty.obanyouthcafe@hotmail.co.uk", locationLine: "Young people in Oban, Lorn and the Isles · confirm age range and current schedule" });
add("Oban", "grants", "oban-common-good-fund", "Oban Common Good Fund", "Local project and community-benefit grant fund", "This Oban-specific fund considers one-off projects that meet a local need or directly benefit Oban residents. Individuals and constituted voluntary or charitable groups may apply if they meet the published criteria and provide the required documents; awards are not guaranteed. The trustees meet quarterly and set application deadlines, so check the current dates and whether other funding sources must be tried first.", "01546 605522", "https://www.argyll-bute.gov.uk/my-community/oban-common-good-fund", "Argyll and Bute Council — Oban Common Good Fund", { email: "commongoodfunds@argyll-bute.gov.uk", locationLine: "Oban-specific · quarterly deadlines · project/community benefit; not an emergency cash grant" });

// Fort William: Lochaber-specific housing, counselling, youth and advice routes.
add("Fort William", "housing", "lochaber-housing-association", "Lochaber Housing Association", "Social housing application and housing advice", "Lochaber Housing Association is a Highland Housing Register partner. The register uses one application form for participating social landlords; contact the association to discuss the application process, property eligibility and current waiting arrangements. A housing application does not guarantee an offer.", "01397 702530", "https://www.highland.gov.uk/housing/housing-associations-highlands", "Highland Council / Lochaber Housing Association", { address: "101 High Street, Fort William PH33 6DG", email: "info@lochaberhousing.org.uk", locationLine: "Shared housing-register partner · confirm criteria and current waiting arrangements" });
add("Fort William", "housing", "highland-council-lochaber-housing", "Highland Council — Lochaber housing office", "Local housing options and emergency housing contact", "The Highland Council lists its Lochaber housing office in Fort William. Housing staff can advise on housing and property services; call the central daytime line and ask for Lochaber. For out-of-hours housing emergencies, use the separately listed council number.", "01349 886602", "https://www.highland.gov.uk/housing/housing-property-offices", "Highland Council", { address: "Charles Kennedy Building, Achintore Road, Fort William PH33 6RQ", alternatePhone: "Out of hours: 01349 886691", email: "housing.lochaber@highland.gov.uk", locationLine: "Weekday daytime contact and separate out-of-hours emergency contact" });
add("Fort William", "housing", "lochaber-care-and-repair", "Lochaber Care and Repair", "Housing repairs and adaptations advice for older or disabled residents", "Highland Council lists Lochaber Housing Association as the local Care and Repair partner. The service can advise on home repairs or adaptations and arrange a visit. Contact to check eligibility and the current area service; it is not a general emergency repair contractor.", "01397 706444", "https://www.highland.gov.uk/housing/care-repair-service/2", "Highland Council / Lochaber Housing Association", { email: "info@lcr.org.uk", locationLine: "Lochaber area · advice or visit by arrangement; check current eligibility" });
add("Fort William", "programs", "community-mental-health-team", "Lochaber Community Mental Health Team", "Adult community mental-health team contact", "Highland Council publishes the Lochaber Community Mental Health Team base at Fort William Health Centre. Contact the team to ask about assessment, referral and current clinic access. The published contact list provides direct local numbers; this listing is not an emergency service.", "01397 709830", "https://www.highland.gov.uk/download/downloads/id/11971/community_mental_health_team_contact_details.pdf", "Highland Council / NHS Highland", { alternatePhone: "01397 707060", address: "Fort William Health Centre, Camaghael, Fort William PH33 7AQ", locationLine: "Lochaber team · contact for referral and current appointment arrangements" });
add("Fort William", "programs", "lochaber-womens-aid", "Lochaber Women's Aid", "Confidential domestic-abuse support and safety planning", "Highland Council lists Lochaber Women's Aid as a local service for domestic-abuse support. Contact the organisation to discuss safe ways to communicate, available support and the right route for your circumstances. If someone is in immediate danger, call 999.", "01397 705734", "https://www.highland.gov.uk/adults-older-people/domestic-abuse", "Highland Council / Lochaber Women's Aid", { email: "lwa@lochaberwomensaid.org", locationLine: "Confidential support · contact only when safe; emergency danger call 999" });
add("Fort William", "programs", "lochaber-hope-counselling", "Lochaber Hope Community Hub", "Counselling, mentoring, family and practical wellbeing support", "The Fort William-based charity offers counselling, mentoring, family support and community activities across Lochaber. Contact to discuss what support is suitable, cost or contribution, current availability and any referral process. The charity says its team responds during weekday office hours.", "01397 704836", "https://www.lochaberhope.org.uk/contactus", "Lochaber Hope", { address: "Waverley House, High Street, Fort William PH33 6XX", email: "admin@lochaberhope.org.uk", locationLine: "Weekdays 9am–5pm contact; community hub drop-in hours listed separately" });
add("Fort William", "peer", "ewens-room-community-wellbeing", "Ewen's Room — Open Doors community drop-in", "Community listening, connection and wellbeing session", "Ewen's Room runs an Open Doors session at Fort William Library with friendly conversation, refreshments and time to talk. The provider lists Tuesday 10:30am–12:30pm; contact before attending to confirm the current session. It supports people affected by mental-health difficulties and is not an emergency response service.", "01967 401130", "https://ewensroom.com/services/open-doors-community-drop-in/", "Ewen's Room", { address: "Fort William Library, Fort William", email: "info@ewensroom.com", locationLine: "Tuesday 10:30am–12:30pm listed · call to verify any schedule changes" });
add("Fort William", "programs", "ewens-room-youth-counselling", "Ewen's Room — free counselling in Lochaber", "Free counselling for school pupils and young adults", "Ewen's Room offers free one-to-one counselling for pupils at Ardnamurchan High School and Mallaig High School, plus counselling outside school for people under 30 living in Lochaber where the service can offer it. Self-referral is possible by email. Ask about current eligibility, waiting time and appointment format. This is not an emergency response service.", "01967 401130", "https://ewensroom.com/services/counselling/", "Ewen's Room", { address: "c/o Voluntary Action Lochaber, Claggan Road, Fort William PH33 6PH", email: "appointments@ewensroom.com", locationLine: "P6–S6 pupils at named schools; other Lochaber residents under 30 may be eligible" });
add("Fort William", "grants", "lochaber-citizens-advice", "Lochaber Citizens Advice Bureau", "Free, confidential advice on benefits, money, housing and debt", "Lochaber CAB offers local advice by drop-in, appointment and phone, with home visits where needed. Contact the bureau to describe what help you need and confirm the best current appointment route; advisers can explain options but do not decide benefit eligibility.", "01397 705311", "https://www.lochabercab.org.uk/get-advice", "Lochaber Citizens Advice Bureau", { address: "Dudley Road, Fort William PH33 6JB", locationLine: "Phone lines listed 10am–3pm weekdays; bureau hours and home visits require confirmation" });
add("Fort William", "food.essentials", "lochaber-foodbank", "Lochaber Foodbank — Fort William distribution point", "Emergency food parcels by voucher", "Lochaber Foodbank provides emergency food parcels and says visitors need a valid foodbank voucher. Its Fort William site publishes weekday distribution sessions; contact the foodbank or referral agency first to confirm voucher access, current times and availability before travelling.", "01397 700212", "https://www.lochaberfoodbank.org/locations/", "Lochaber Foodbank", { address: "Unit 4, Airds Crossing, High Street, Fort William PH33 6EU", alternatePhone: "07421 087463", locationLine: "Voucher required · published sessions Monday, Wednesday and Friday; call to confirm current opening and supply" });

// Additional, distinct pathways surfaced during locality-depth review.
add("Dumfries", "programs", "issu18-young-peoples-substance-service", "ISSU18 — young people’s substance-use service", "Specialist support for young people affected by substance use", "NHS Dumfries and Galloway's ISSU18 team supports people under 18 affected by their own or a family member's substance use, including where mental-health or other complex needs are present. Appointments can be arranged at The Willows, with home or online appointments also described. Contact the service to confirm eligibility and current intake.", "01387 244622", "https://dghscp.co.uk/camhs/issu-18/", "Dumfries and Galloway Health and Social Care Partnership", { address: "The Willows, Crichton Central, Dumfries DG1 4TG", locationLine: "Children and young people under 18 · service across Dumfries and Galloway · referral route varies by need" });
add("Dumfries", "programs", "crisis-assessment-treatment-service", "NHS Crisis Assessment and Treatment Service — Dumfries area", "24-hour community mental-health crisis assessment and home treatment", "The NHS nurse-led team provides urgent psychiatric assessment and home-based treatment for people experiencing a mental-health crisis. It covers most of Dumfries and Galloway except Wigtownshire. Urgent referrals are generally made by a GP or health professional; people already receiving care can contact the team for urgent input. If you need urgent health advice, call NHS 24 on 111; call 999 for immediate danger.", "01387 246246", "https://dghscp.co.uk/crisis-assessment-and-treatment-service/", "Dumfries and Galloway Health and Social Care Partnership", { address: "Dumfries and Galloway Royal Infirmary switchboard, Dumfries", locationLine: "24-hour service · coverage excludes Wigtownshire, which has a separate crisis arrangement" });
add("Dumfries", "peer", "unpaid-carers-support", "Dumfries and Galloway Carers Centre", "Information, support planning and connection for unpaid carers", "The Health and Social Care Partnership describes support for unpaid carers including Adult Carer Support Plans, Young Carer Statements, breaks, emergency planning, training and wellbeing support. Contact the Carers Centre to discuss local eligibility, availability and how to access a support plan.", null, "https://dghscp.co.uk/working-well/social-wellbeing/", "Dumfries and Galloway Health and Social Care Partnership", { locationLine: "Unpaid adult and young carers · regional service with local routes; contact to confirm current arrangements" });
add("Stranraer", "programs", "being-there-family-support", "Being There — support for families affected by substance use", "Confidential support for family members and friends", "Alcohol and Drug Support South West Scotland describes Being There as free, confidential, non-judgemental support for family members and friends affected by another person's alcohol or drug use. It offers a listening ear and practical advice. Contact to discuss the best local or remote route and current service availability.", "0333 880 6950", "https://www.adssws.co.uk/being-there/", "Alcohol and Drug Support South West Scotland / Dumfries and Galloway Health and Social Care Partnership", { email: "BeingThere@adssws.co.uk", locationLine: "Support for family and friends · regional service; confirm current Stranraer access" });
add("Stranraer", "programs", "dgmha-west-outreach", "DGMHA West Outreach — Stranraer and Newton Stewart", "Flexible community mental-health and daily-living support", "Dumfries and Galloway Mental Health Association describes a West outreach team offering individually assessed, flexible support at home or to access community life for adults with mental-health needs. The team works with community mental-health and social-work services. Contact the association to discuss eligibility, assessment and current capacity.", null, "https://dgmha.org/service-areas/stranraer-outreach/", "Dumfries and Galloway Mental Health Association", { locationLine: "Adults · covers Stranraer and Newton Stewart · individual assessment required" });
add("Stranraer", "programs", "employability-hub", "Stranraer Employability Hub", "Local employment, money and wellbeing support", "The Dumfries and Galloway Local Employability and Skills Partnership lists one-to-one help into work, paid placements, volunteering, training, digital skills, budgeting and health and wellbeing support at its Stranraer hub. Published hours vary by weekday; contact or check the current page before attending.", null, "https://dgworks.dumfriesandgalloway.gov.uk/find-support/find-support-your-doorstep/employability-hub-stranraer", "Dumfries and Galloway Local Employability and Skills Partnership", { address: "31 Queen Street, Stranraer DG9 7LQ", locationLine: "Tue–Thu 10am–3pm; Fri 9am–2pm listed · check for changes" });
add("Elgin", "programs", "mental-health-social-work", "Moray Council — Mental Health Social Work Team", "Recovery-focused assessment, information and social-work support", "Moray Council's team works within the integrated community mental-health team at Dr Gray's Hospital. It offers information, advice, assessment and recovery-focused support for adults experiencing mental-health difficulties; self-referral and professional referrals are described. Call the Access Care Team to ask for the appropriate route.", "01343 563999", "https://www.moray.gov.uk/social-care-and-health/community-care-mental-health/", "Moray Council", { alternatePhone: "Mental Health Social Work Team: 01343 567376", address: "Pluscarden Clinic, Dr Gray's Hospital, Elgin", locationLine: "Adults in Moray · Access Care Team is the usual first contact" });
add("Elgin", "peer", "moray-mental-talk", "Moray MenTalk — peer connection and wellbeing", "Community peer-support group", "Moray MenTalk describes a peer-support community with in-person meetings in Elgin and online community connection. Check the group's current schedule, venue and participation arrangements before travelling; peer support is not a substitute for emergency or clinical care.", null, "https://moraymentalk.co.uk/", "Moray MenTalk", { locationLine: "Moray community · Elgin meetings reported; confirm current schedule and venue" });
add("Elgin", "programs", "moray-womens-aid-community-support", "Moray Women's Aid — community and therapeutic support", "Community-based support for women affected by domestic abuse", "Moray Women's Aid describes community outreach for people who cannot access its Elgin base or who live in isolated areas. Counselling is for people already receiving the organisation's support, and peer groups run during term time. Contact the service to discuss safety, eligibility and the appropriate current route.", null, "https://moraywomensaid.co.uk/community-therapeutic-services/", "Moray Women's Aid", { address: "Marleon House, Elgin", locationLine: "Women affected by domestic abuse · counselling and peer group access has service-specific criteria" });
add("Elgin", "housing", "sacro-supported-accommodation", "Sacro — Elgin housing support unit", "Supported accommodation and tenancy support", "Community Justice Scotland's current directory describes Sacro supported accommodation in Elgin for adults 18+ who are homeless, with staff support and key-worker planning. Moray Council referral follows a homelessness presentation; non-residential support may be considered. Contact Sacro or Moray Council to establish the current referral route and availability. Accommodation is not guaranteed.", "01343 559737", "https://communityjustice.scot/community-support-service/moray/housing-support/", "Community Justice Scotland / Sacro", { email: "kdonaldson@sacro.org.uk", locationLine: "Adults 18+ · council referral after homelessness presentation · availability must be confirmed" });
add("Oban", "programs", "argyll-bute-recovery-service", "Argyll and Bute Recovery Service — Oban", "Community substance-use and family support", "The local Kinship Scotland service directory lists an Argyll and Bute Recovery Service office in Oban supporting people affected by alcohol or other substance misuse, including family members. Contact the provider to confirm the current operator, referral route, eligibility and local appointment arrangements.", null, "https://kinship.scot/for-kinship-carers/support/services/services-in-argyll-and-bute/", "Kinship Scotland local services directory", { locationLine: "Oban office listed in Argyll and Bute · confirm current provider contact and access" });
add("Oban", "grants", "citizens-advice-benefits-housing", "Argyll and Bute Citizens Advice Bureau — benefits and housing advice", "Free confidential welfare, debt and housing advice", "The local Citizens Advice Bureau offers free, impartial and confidential advice, including help to understand rights and respond to urgent crises. Advisers can explain benefit and housing options, but do not award benefits or guarantee funding. Contact the bureau to confirm the current Oban appointment or outreach route.", null, "https://argyll-bute.cas.org.uk/", "Argyll and Bute Citizens Advice Bureau", { locationLine: "Area-wide bureau serving Oban and Argyll and Bute · confirm appointment options and opening hours" });
add("Oban", "housing", "home-secure-argyll", "Home Secure Argyll — Oban housing advice and early support", "Housing-risk advice and tenancy support connection", "Home Secure Argyll helps people address housing worries before crisis, including rent arrears, eviction risk and changing housing needs. The project lists an Oban-based Carr Gomm Housing Support Worker. Contact the named service to confirm its current remit and eligibility. It does not offer or guarantee accommodation.", "07561 296134", "https://abcab.cas.org.uk/get-advice/our-services/home-secure-argyll/", "Argyll and Bute Citizens Advice Bureau / Carr Gomm", { email: "angiebird@carrgomm.org", locationLine: "Oban · early housing-risk support and referral; not an emergency bed service" });
add("Fort William", "programs", "west-lochaber-community-mental-health-team", "NHS Highland — West Lochaber Community Mental Health Team", "Local community mental-health support", "Highland Council publishes contact details for the West Lochaber Community Mental Health Team based at Fort William Health Centre. Contact the team to discuss its current remit, referral options and appointments; for urgent health advice call NHS 24 on 111, and call 999 for immediate danger.", "01397 709830", "https://www.highland.gov.uk/download/downloads/id/11971/community_mental_health_team_contact_details", "Highland Council / NHS Highland", { alternatePhone: "01397 707060", address: "Fort William Health Centre, Camaghael, Fort William PH33 7AQ", locationLine: "West Lochaber · call to confirm eligibility, referral and hours" });
add("Fort William", "programs", "ewens-room-adult-counselling", "Ewen's Room — counselling for Lochaber adults under 30", "Person-centred counselling for young adults", "Ewen's Room says Lochaber residents under 30 outside its named school counselling programme may be offered counselling, usually online, subject to the service's current capacity and arrangements. Contact the appointments team to confirm eligibility and waiting times. This is not an emergency response service.", null, "https://ewensroom.com/services/counselling/", "Ewen's Room", { email: "appointments@ewensroom.com", locationLine: "Lochaber residents under 30 · subject to current service availability" });
add("Fort William", "grants", "highland-welfare-support-team", "Highland Council — Welfare Support Team", "Benefits checks and applications support", "Highland Council's Fort William-area leaflet describes a free, confidential Welfare Team that can identify benefit entitlements and help complete applications, including support with some urgent household costs. Contact the team to verify current service scope, eligibility and response times; payments are assessed and not guaranteed.", "0800 090 1004", "https://www.highland.gov.uk/download/downloads/id/22952/fort_william_area_-_coronavirus_help_and_support_leaflet.pdf", "Highland Council", { email: "welfare.support@highland.gov.uk", locationLine: "Highland residents · published contact hours 9am–5pm; confirm current arrangements" });

// Distinct local urgent housing routes complete the six-category access baseline for this cohort.
add("Dumfries", "hotlines", "urgent-homelessness-tonight", "Dumfries Council — urgent homelessness help tonight", "Urgent accommodation advice for people without a place to stay", "If you have no place to stay tonight, the council publishes a local daytime contact for Dumfries and a separate free number after 5pm or on weekends. The council assesses the circumstances and does not guarantee accommodation. If there is immediate danger to life, call 999.", "01387 260783", "https://www.dumfriesandgalloway.gov.uk/housing/homelessness", "Dumfries and Galloway Council", { alternatePhone: "After 5pm or weekends: 0303 333 3001", locationLine: "Dumfries urgent-housing access · day and after-hours numbers differ; call 999 for immediate danger" });
add("Stranraer", "hotlines", "urgent-homelessness-tonight", "Stranraer Council — urgent homelessness help tonight", "Urgent accommodation advice for people without a place to stay", "If you have no place to stay tonight, the council publishes a local urgent contact for Stranraer and a separate free number after 5pm or on weekends. The council assesses the circumstances and does not guarantee accommodation. If there is immediate danger to life, call 999.", "01776 888312", "https://www.dumfriesandgalloway.gov.uk/housing/homelessness", "Dumfries and Galloway Council", { alternatePhone: "After 5pm or weekends: 0303 333 3001", locationLine: "Stranraer urgent-housing access · day and after-hours numbers differ; call 999 for immediate danger" });
add("Elgin", "hotlines", "moray-out-of-hours-homelessness", "Moray Council — out-of-hours urgent homelessness and safety", "Out-of-hours emergency housing and safety contact", "Moray Council advises people with an immediate risk of homelessness who need somewhere to stay to call its out-of-hours contact during evenings, weekends and public holidays. The line is for genuine emergencies; non-urgent requests should go through daytime housing options. Call 999 for an immediate threat to life.", "03457 565656", "https://www.moray.gov.uk/housing-and-homelessness/who-should-i-contact/", "Moray Council", { alternatePhone: "Daytime housing options: 0300 123 4566", locationLine: "Elgin and Moray · out-of-hours emergency contact; office hours 8:45am–5pm weekdays" });
add("Oban", "hotlines", "argyll-bute-out-of-hours-housing", "Argyll and Bute Council — out-of-hours housing emergency", "Urgent out-of-hours homelessness and housing contact", "Argyll and Bute Council publishes one out-of-hours number for all areas. Use it for an urgent housing or homelessness matter outside office hours; non-urgent enquiries should go to the Oban housing office during the day. The council does not promise accommodation or a particular response outcome. Call 999 for immediate danger to life.", "0345 056 5457", "https://www.argyll-bute.gov.uk/housing/housing-useful-contacts", "Argyll and Bute Council", { alternatePhone: "Oban housing office daytime: 01631 572902", locationLine: "All council areas · out-of-hours route; office hours are Monday–Friday, 9am–5pm" });
add("Fort William", "hotlines", "highland-out-of-hours-housing", "Highland Council — out-of-hours housing emergency", "Urgent out-of-hours housing and homelessness contact", "Highland Council's current contact page lists this number for out-of-hours housing and homelessness emergencies, including the Lochaber area. Use the daytime Lochaber housing contact for non-urgent matters. If there is an immediate threat to life, call 999.", "01349 886691", "https://www.highland.gov.uk/homepage/33/contact-us", "Highland Council", { alternatePhone: "Daytime Highland Housing Options: 01349 886602", locationLine: "Out-of-hours housing emergency contact for Highland Council areas" });
add("Fort William", "hotlines", "highland-emergency-social-work-service", "Highland Council — Emergency Social Work Service", "Out-of-hours urgent social-work contact", "Highland Council's Emergency Social Work Service supports urgent social problems including serious child welfare concerns, family breakdown, older people at risk and people with disabilities or mental-health needs requiring urgent help. It operates weekday evenings and overnight, and 24 hours at weekends and public holidays. It is not a clinical crisis line; call 111 for urgent health advice and 999 for immediate danger.", "0808 175 3646", "https://www.highland.gov.uk/health-social-care/emergency-social-work-service", "Highland Council", { email: "ESWS@highland.gov.uk", locationLine: "Weekdays 5pm–9am; weekends and public holidays 24 hours" });
add("Dumfries", "programs", "dg-advocacy-service", "Dumfries and Galloway Advocacy Service", "Independent individual and collective advocacy", "This free independent service supports adults 18+ across Dumfries and Galloway, including people with mental ill-health, learning disability, autism and unpaid carers. Advocates help people understand their options and express their own views in care, treatment and other decisions; they do not provide legal representation. Self-referral is available.", "01387 247237", "https://www.dgadvocacy.co.uk/contact/", "Dumfries and Galloway Advocacy Service / NHS Dumfries and Galloway", { address: "Hestan House, Crichton Business Park, Bankend Road, Dumfries DG1 4TA", email: "info@dgadvocacy.co.uk", locationLine: "Adults 18+ in Dumfries and Galloway · weekday office hours listed 9:30am–3:30pm" });
add("Dumfries", "programs", "dg-rape-and-sexual-abuse-support", "Dumfries and Galloway RASAC — sexual-abuse support", "Confidential specialist support and advocacy", "Rape Crisis Scotland lists the regional Dumfries and Galloway Rape and Sexual Abuse Centre for people affected by sexual violence. Contact the service to discuss its current confidential support, referral route and availability; a waiting list may apply. If you are in immediate danger, call 999.", "01387 253113", "https://www.rapecrisisscotland.org.uk/help-local-rcc", "Rape Crisis Scotland / Dumfries and Galloway RASAC", { locationLine: "Regional service based in Dumfries · contact to confirm eligibility and current waiting time" });
add("Oban", "programs", "home-start-lorn-family-support", "Home-Start Lorn — family support in Oban and North Argyll", "Volunteer home-visiting and practical family support", "Home-Start Lorn supports parents and carers with children under five across Oban, North Argyll and nearby communities. Trained volunteers provide practical and emotional support through home visits and a family centre. Contact the team to discuss eligibility, referral and current availability.", "01631 566749", "https://homestartlorn.org.uk/contact", "Home-Start Lorn / Argyll and Bute Council", { address: "12–14 Stevenson Street, Oban PA34 5NA", email: "admin@homestartlorn.org.uk", locationLine: "Families with children under 5 · Oban and North Argyll catchment" });
add("Oban", "hotlines", "argyll-bute-out-of-hours-social-work", "Argyll and Bute Council — out-of-hours Social Work", "Urgent social-work contact for safeguarding and urgent support", "Argyll and Bute Council lists an out-of-hours Social Work contact for emergencies and urgent concerns about children, young people and vulnerable adults. The route covers the whole council area; for a non-urgent enquiry, call the daytime Social Work number. Call 999 if anyone is in immediate danger.", "01631 566491", "https://www.argyll-bute.gov.uk/social-care-and-health/contact-social-work", "Argyll and Bute Council", { alternatePhone: "01631 569712", locationLine: "Area-wide out-of-hours service · weekday daytime Social Work: 01546 605517" });

